	int t;
	cin>>t;
	while(t--){
	    int n,k;
	    string s;
	    cin>>n>>k>>s;
	    
	    stack<int> st1,st2;
	    
	    bool cn=true;
	    for(int i=0;i<n;i++){
	        if(s[i]=='G'){
	            if(st1.size()<k+1){
	                st1.push('G');
	            }
	            else{
	                if(st2.size()<k+1){
	                    st2.push('G');
	                }
	                else{
	                    cn=false;
	                    break;
	                }
	            }
	        }
	        else{
	            if(st2.size()==0){
	                continue;
	            }
	            else{
	                if(st2.size()<k){
	                    st2.push('I');
	                    st2.push('I');
	                }
	                else{
	                    cn=false;
	                    break;
	                }
	            }
	        }
	    }
	    
	    if(cn==false){
	        cout<<"NO"<<endl;
	    }
	    else{
	        cout<<"YES"<<endl;
	    }
	    
	}

}
